import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;

    static class Edge {
        int u, v, w;
        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static class AdjEdge {
        int to, w;
        AdjEdge(int to, int w) {
            this.to = to;
            this.w = w;
        }
    }

    static class DSU {
        int[] p, sz;

        DSU(int n) {
            p = new int[n + 1];
            sz = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }

        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;
            if (sz[ra] < sz[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            p[rb] = ra;
            sz[ra] += sz[rb];
            return true;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int B = Integer.parseInt(st.nextToken());

        Edge[] edges = new Edge[B];
        for (int i = 0; i < B; i++) {
            st = new StringTokenizer(br.readLine());
            int I = Integer.parseInt(st.nextToken());
            int J = Integer.parseInt(st.nextToken());
            int P = Integer.parseInt(st.nextToken());
            edges[i] = new Edge(I, J, P);
        }

        Arrays.sort(edges, (a, b) -> Integer.compare(b.w, a.w));

        DSU dsu = new DSU(N);

        ArrayList<AdjEdge>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            adj[i] = new ArrayList<>();
        }

        int added = 0;
        for (Edge e : edges) {
            if (dsu.union(e.u, e.v)) {
                adj[e.u].add(new AdjEdge(e.v, e.w));
                adj[e.v].add(new AdjEdge(e.u, e.w));
                added++;
                if (added == N - 1) break;
            }
        }

        int LOG = 1;
        while ((1 << LOG) <= N) LOG++;

        int[][] up = new int[LOG][N + 1];
        int[][] mn = new int[LOG][N + 1];
        int[] depth = new int[N + 1];
        int[] minToParent = new int[N + 1];

        Arrays.fill(depth, -1);
        depth[1] = 0;
        minToParent[1] = INF;

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(1);

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (AdjEdge e : adj[u]) {
                if (e.to == up[0][u]) continue;
                depth[e.to] = depth[u] + 1;
                up[0][e.to] = u;
                minToParent[e.to] = e.w;
                stack.push(e.to);
            }
        }

        for (int v = 1; v <= N; v++) {
            mn[0][v] = minToParent[v];
        }
        mn[0][0] = INF;

        for (int k = 1; k < LOG; k++) {
            for (int v = 1; v <= N; v++) {
                int mid = up[k - 1][v];
                up[k][v] = up[k - 1][mid];
                mn[k][v] = Math.min(mn[k - 1][v], mn[k - 1][mid]);
            }
            up[k][0] = 0;
            mn[k][0] = INF;
        }

        st = new StringTokenizer(br.readLine());
        int C = Integer.parseInt(st.nextToken());

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < C; i++) {
            st = new StringTokenizer(br.readLine());
            int X = Integer.parseInt(st.nextToken());
            int Y = Integer.parseInt(st.nextToken());
            sb.append(query(X, Y, LOG, up, mn, depth)).append('\n');
        }

        System.out.print(sb);
    }

    static int query(int a, int b, int LOG, int[][] up, int[][] mn, int[] depth) {
        int ans = INF;

        if (depth[a] < depth[b]) {
            int tmp = a;
            a = b;
            b = tmp;
        }

        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if ((diff & (1 << k)) != 0) {
                ans = Math.min(ans, mn[k][a]);
                a = up[k][a];
            }
        }

        if (a == b) return ans;

        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                ans = Math.min(ans, mn[k][a]);
                ans = Math.min(ans, mn[k][b]);
                a = up[k][a];
                b = up[k][b];
            }
        }

        ans = Math.min(ans, mn[0][a]);
        ans = Math.min(ans, mn[0][b]);

        return ans;
    }
}
